fn equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length, iterate over both in parallel
    // Compare each pair of elements and collect the boolean results into a Vec<bool>
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x == y)
     .collect()
}